sed -i '/val icon = when (goal.type) {/,/Text(icon, fontSize = 12.sp)/c\            val icon = when (goal.type) {\n                GoalType.SCORE -> "⭐"\n                GoalType.CLEAR_JELLY -> "🧊"\n                GoalType.CLEAR_CHOCOLATE -> "🍫"\n                GoalType.COLLECT_INGREDIENTS -> "🍒"\n                GoalType.COLLECT_COLOR -> "🍬"\n            }\n            val actionText = when (goal.type) {\n                GoalType.SCORE -> "Score"\n                GoalType.CLEAR_JELLY -> "Clear Jelly"\n                GoalType.CLEAR_CHOCOLATE -> "Clear Choco"\n                GoalType.COLLECT_INGREDIENTS -> "Drop Cherries"\n                GoalType.COLLECT_COLOR -> "Collect ${goal.targetColor?.displayName ?: \"Candy\"}"\n            }\n            Text(icon, fontSize = 14.sp)' app/src/main/java/com/example/ui/screens/GamePlayScreen.kt
sed -i 's/text = if (isDone) "DONE ✓" else "$remaining"/text = if (isDone) "DONE ✓" else "$actionText: $remaining"/' app/src/main/java/com/example/ui/screens/GamePlayScreen.kt
